// Implement custom map
Array.prototype.myMap = function (callback) {
  const result = [];

  for (let i = 0; i < this.length; i++) {
    // callback receives currentValue, index, and the original array
    result.push(callback(this[i], i, this));
  }

  return result;
};

const arr = [1, 2, 3, 4];
const res = arr.myMap((num) => num * 2);

console.log(res); // [2, 4, 6, 8]

// Implement custom filter
Array.prototype.myFilter = function (callback) {
  const result = [];

  for (let i = 0; i < this.length; i++) {
    // Only keep elements where the callback returns true
    if (callback(this[i], i, this)) {
      result.push(this[i]);
    }
  }

  return result;
};

const arr2 = [1, 2, 3, 4, 5];
const res2 = arr2.myFilter((num) => num % 2 === 0);

console.log(res2); // [2, 4]

