// Polyfill for includes
Array.prototype.myIncludes = function (searchElement) {
  for (let i = 0; i < this.length; i++) {
    if (this[i] === searchElement) {
      return true;
    }
  }

  return false;
};

const ar = [10, 20, 30];
console.log(ar.myIncludes(20)); // true
console.log(ar.myIncludes(50)); // false

// Chain multiple array methods
const chainArrMethod = (arr) => {
  return arr
    .filter((num) => num % 2 === 0) // keep only even numbers
    .map((num) => num * 2)          // double each even number
    .reduce((acc, curr) => acc + curr, 0); // sum them all up
};

console.log(chainArrMethod([1, 2, 3, 4, 5, 6])); // 24

// Implement custom reduce
Array.prototype.myReduce = function (callback, initialValue) {
  let accumulator = initialValue;

  for (let i = 0; i < this.length; i++) {
    // Update the accumulator on every iteration using the callback
    accumulator = callback(accumulator, this[i], i, this);
  }

  return accumulator;
};

const arr3 = [1, 2, 3, 4];

const sum = arr3.myReduce((acc, curr) => {
  return acc + curr;
}, 0);

console.log(sum); // 10
